import React, { useState, useEffect } from "react";
import { X } from "lucide-react";

function JobForm({ job, onClose, onSubmit }) {
  const [formData, setFormData] = useState({
    title: "",
    role: "",
    skillset: "",
    ctc: "",
    location: "",
    experience: "",
    jobType: "Full-time",
    department: "",
    description: "",
    responsibilities: "",
    qualifications: "",
    benefits: "",
    deadline: "",
  });

  useEffect(() => {
    if (job) setFormData(job);
  }, [job]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = () => {
    if (
      !formData.title ||
      !formData.role ||
      !formData.skillset ||
      !formData.ctc ||
      !formData.location ||
      !formData.experience ||
      !formData.description
    ) {
      alert("Please fill all required fields");
      return;
    }
    onSubmit(formData);
  };

  const resetForm = () => {
    setFormData({
      title: "",
      role: "",
      skillset: "",
      ctc: "",
      location: "",
      experience: "",
      jobType: "Full-time",
      department: "",
      description: "",
      responsibilities: "",
      qualifications: "",
      benefits: "",
      deadline: "",
    });
    onClose();
  };

  return (
    <div className="modal-overlay">
      <div className="modal-container">
        {/* Header */}
        <div className="modal-header">
          <h2>{job ? "Edit Job" : "Add New Job"}</h2>
          <button className="close-btn" onClick={resetForm}>
            <X size={22} />
          </button>
        </div>

        {/* Form Content */}
        <div className="modal-body">
          {[
            { label: "Job Title *", name: "title", type: "text" },
            { label: "Role/Position *", name: "role", type: "text" },
            { label: "Skillset *", name: "skillset", type: "text" },
            { label: "CTC *", name: "ctc", type: "text" },
            { label: "Location *", name: "location", type: "text" },
            { label: "Experience *", name: "experience", type: "text" },
            { label: "Department", name: "department", type: "text" },
            { label: "Deadline", name: "deadline", type: "date" },
          ].map((field, i) => (
            <div className="form-group" key={i}>
              <label>{field.label}</label>
              <input
                type={field.type}
                name={field.name}
                value={formData[field.name]}
                onChange={handleChange}
              />
            </div>
          ))}

          <div className="form-group">
            <label>Job Type</label>
            <select name="jobType" value={formData.jobType} onChange={handleChange}>
              <option>Full-time</option>
              <option>Part-time</option>
              <option>Contract</option>
              <option>Internship</option>
            </select>
          </div>

          <div className="form-group full-width">
            <label>Description *</label>
            <textarea name="description" rows="4" value={formData.description} onChange={handleChange} />
          </div>

          <div className="form-group full-width">
            <label>Responsibilities</label>
            <textarea name="responsibilities" rows="3" value={formData.responsibilities} onChange={handleChange} />
          </div>

          <div className="form-group full-width">
            <label>Qualifications</label>
            <textarea name="qualifications" rows="3" value={formData.qualifications} onChange={handleChange} />
          </div>

          <div className="form-group full-width">
            <label>Benefits & Perks</label>
            <textarea name="benefits" rows="3" value={formData.benefits} onChange={handleChange} />
          </div>
        </div>

        {/* Footer */}
        <div className="modal-footer">
          <button className="btn primary" onClick={handleSubmit}>
            {job ? "Update Job" : "Add Job"}
          </button>
          <button className="btn secondary" onClick={resetForm}>
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
}

export default JobForm;
